<script setup lang="ts">
import {ref,watch} from 'vue';import {catalogApi} from '@/api';import ItemCard from '@/components/ItemCard.vue';
const props=defineProps<{kind:'lessons'|'equipment'|'instructors'}>();
const items=ref<any[]>([]),loading=ref(true),error=ref(''),category=ref('all');
const titles={lessons:['Занятия на склоне','Выбирай программу для своего уровня катания'],equipment:['Подготовься к покорению склонов','Выбирай необходимое снаряжение для комфортного и безопасного катания. Всё оборудование доступно для аренды на удобный период'],instructors:['Наши инструкторы','Опытные специалисты помогут освоить склоны']};
const categories={lessons:[['all','Все'],['ski','Лыжи'],['snowboard','Сноуборд'],['individual','Индивидуальные'],['group','Групповые'],['kids','Детские']],equipment:[['all','Всё'],['ski','Лыжи'],['snowboard','Сноуборды'],['boots','Ботинки'],['helmet','Шлемы'],['goggles','Маски'],['kit','Комплекты']],instructors:[['all','Все']]};
async function load(){loading.value=true;error.value='';try{items.value=props.kind==='lessons'?await catalogApi.lessons(category.value==='all'?undefined:category.value as any):props.kind==='equipment'?await catalogApi.equipment(category.value==='all'?undefined:category.value as any):await catalogApi.instructors()}catch(e){error.value='Не удалось загрузить'}finally{loading.value=false}}
watch(()=>[props.kind,category.value],load,{immediate:true});watch(()=>props.kind,()=>category.value='all');
</script><template><div class="container section section--top"><h1 class="h1">{{titles[kind][0]}}</h1><p class="lead">{{titles[kind][1]}}</p><div class="filters"><button v-for="c in categories[kind]" :key="c[0]" class="filter-pill" :class="{'filter-pill--active':category===c[0]}" @click="category=c[0]">{{c[1]}}</button></div><div v-if="loading" class="card panel">Загружаем данные...</div><div v-else-if="error" class="card panel empty-state"><div class="empty-state__symbol">↻</div><p class="empty-state__title">{{error}}</p><button class="btn btn--outline btn--sm" @click="load">Повторить</button></div><div v-else-if="!items.length" class="card panel">Пока нет доступных предложений.</div><div v-else class="grid grid--3"><ItemCard v-for="item in items" :key="item.id" :item="item" :kind="kind"/></div></div></template>
